import { Component, Prop, Emit } from 'vue-property-decorator';
import { PersistentSettingComponent } from '../../common/persistent-setting';
import SettingsMenuItem from '../../settings-menu/item/index.vue';
import Checkbox from '../../input/checkbox/index.vue';

@Component({
    name: 'SettingsItemCheckbox',
    components: {
        SettingsMenuItem,
        Checkbox
    }
})
export default class SettingsItemCheckbox extends PersistentSettingComponent<boolean> {
    @Prop({
        type: String,
        required: true
    })
    public label: string;

    @Emit('onChange')
    public onChange() {
        this.value = !this.value;
        return this.value;
    }
}
